using System.Collections.Generic;
using System.Linq;
using Umbraco.Cms.Core.Serialization;

namespace Umbraco.Cms.Core.Models.Blocks;

public class BlockGridEditorDataConverter : BlockEditorDataConverter<BlockGridValue, BlockGridLayoutItem>
{
	public BlockGridEditorDataConverter(IJsonSerializer jsonSerializer)
		: base(jsonSerializer)
	{
	}

	protected override IEnumerable<ContentAndSettingsReference> GetBlockReferences(IEnumerable<BlockGridLayoutItem> layout)
	{
		return layout.SelectMany(ExtractContentAndSettingsReferences).ToArray();
		static IList<ContentAndSettingsReference> ExtractContentAndSettingsReferences(BlockGridLayoutItem item)
		{
			List<ContentAndSettingsReference> list = new List<ContentAndSettingsReference>();
			list.Add(new ContentAndSettingsReference(item.ContentKey, item.SettingsKey));
			list.AddRange(item.Areas.SelectMany((BlockGridLayoutAreaItem area) => area.Items.SelectMany(ExtractContentAndSettingsReferences)));
			return list;
		}
	}
}

