using System;
using System.Collections.Generic;
using System.Linq;
using Umbraco.Cms.Core.Cache.PropertyEditors;
using Umbraco.Cms.Core.Models;
using Umbraco.Cms.Core.Models.Blocks;
using Umbraco.Cms.Core.Models.Validation;
using Umbraco.Cms.Core.PropertyEditors.Validation;
using Umbraco.Cms.Core.Services;
using Umbraco.Extensions;

namespace Umbraco.Cms.Core.PropertyEditors;

public abstract class BlockEditorValidatorBase<TValue, TLayout> : ComplexEditorValidator where TValue : BlockValue<TLayout>, new() where TLayout : class, IBlockLayoutItem, new()
{
	private readonly IBlockEditorElementTypeCache _elementTypeCache;

	protected virtual string ContentDataGroupJsonPath => "ContentData".ToFirstLowerInvariant();

	protected virtual string SettingsDataGroupJsonPath => "SettingsData".ToFirstLowerInvariant();

	protected BlockEditorValidatorBase(IPropertyValidationService propertyValidationService, IBlockEditorElementTypeCache elementTypeCache)
		: base(propertyValidationService)
	{
		_elementTypeCache = elementTypeCache;
	}

	protected IEnumerable<ElementTypeValidationModel> GetBlockEditorDataValidation(BlockEditorData<TValue, TLayout> blockEditorData, PropertyValidationContext validationContext)
	{
		List<ElementTypeValidationModel> list = new List<ElementTypeValidationModel>();
		bool flag = validationContext.Culture == "*";
		string text = (flag ? null : validationContext.Culture.NullOrWhiteSpaceAsNull());
		list.AddRange(GetBlockEditorDataValidation(blockEditorData, text, validationContext.Segment));
		if (text == null)
		{
			IEnumerable<string> enumerable;
			if (!flag)
			{
				IEnumerable<string> culturesBeingValidated = validationContext.CulturesBeingValidated;
				enumerable = culturesBeingValidated;
			}
			else
			{
				enumerable = blockEditorData.BlockValue.Expose.Select((BlockItemVariation e) => e.Culture).WhereNotNull().Distinct();
			}
			foreach (string item in enumerable)
			{
				foreach (string item2 in validationContext.SegmentsBeingValidated.DefaultIfEmpty(null))
				{
					list.AddRange(GetBlockEditorDataValidation(blockEditorData, item, item2));
				}
			}
		}
		else
		{
			foreach (string item3 in validationContext.SegmentsBeingValidated.DefaultIfEmpty(null))
			{
				list.AddRange(GetBlockEditorDataValidation(blockEditorData, null, item3));
			}
		}
		return list;
	}

	private IEnumerable<ElementTypeValidationModel> GetBlockEditorDataValidation(BlockEditorData<TValue, TLayout> blockEditorData, string? culture, string? segment)
	{
		if (blockEditorData.Layout == null)
		{
			yield break;
		}
		Guid[] exposedContentKeys = (from expose in blockEditorData.BlockValue.Expose
			where culture == null || expose.Culture == culture
			select expose.ContentKey).Distinct().ToArray();
		Guid[] exposedSettingsKeys = (from layout in blockEditorData.Layout
			where layout.SettingsKey.HasValue && exposedContentKeys.Contains(layout.ContentKey)
			select layout.SettingsKey.Value).ToArray();
		var array = new[]
		{
			new
			{
				Path = ContentDataGroupJsonPath,
				Items = blockEditorData.BlockValue.ContentData.Where((BlockItemData cd) => exposedContentKeys.Contains(cd.Key)).ToArray()
			},
			new
			{
				Path = SettingsDataGroupJsonPath,
				Items = blockEditorData.BlockValue.SettingsData.Where((BlockItemData sd) => exposedSettingsKeys.Contains(sd.Key)).ToArray()
			}
		};
		string valuesJsonPathPart = "Values".ToFirstLowerInvariant();
		var array2 = array;
		foreach (var group in array2)
		{
			Guid[] array3 = group.Items.Select((BlockItemData x) => x.ContentTypeKey).ToArray();
			if (array3.Length == 0)
			{
				continue;
			}
			Dictionary<Guid, IContentType> allElementTypes = _elementTypeCache.GetMany(array3).ToDictionary((IContentType x) => x.Key);
			for (int i = 0; i < group.Items.Length; i++)
			{
				BlockItemData blockItemData = group.Items[i];
				if (!allElementTypes.TryGetValue(blockItemData.ContentTypeKey, out var value))
				{
					throw new InvalidOperationException($"No element type found with key {blockItemData.ContentTypeKey}");
				}
				ElementTypeValidationModel elementTypeValidationModel = new ElementTypeValidationModel(blockItemData.ContentTypeAlias, blockItemData.Key);
				for (int num2 = 0; num2 < blockItemData.Values.Count; num2++)
				{
					BlockPropertyValue blockPropertyValue = blockItemData.Values[num2];
					IPropertyType propertyType = blockPropertyValue.PropertyType;
					if (propertyType == null)
					{
						throw new ArgumentException("One or more block properties did not have a resolved property type. Block editor values must be resolved before attempting to validate them.", "blockEditorData");
					}
					if (propertyType.VariesByCulture() == (culture != null) && blockPropertyValue.Culture.InvariantEquals(culture) && (!(segment != "*") || (propertyType.VariesBySegment() == (segment != null) && blockPropertyValue.Segment.InvariantEquals(segment))))
					{
						elementTypeValidationModel.AddPropertyTypeValidation(new PropertyTypeValidationModel(propertyType, blockPropertyValue.Value, $"{group.Path}[{i}].{valuesJsonPathPart}[{num2}].value"));
					}
				}
				string[] array4 = elementTypeValidationModel.PropertyTypeValidation.Select((PropertyTypeValidationModel v) => v.PropertyType.Alias).ToArray();
				foreach (IPropertyType compositionPropertyType in value.CompositionPropertyTypes)
				{
					if (!array4.Contains(compositionPropertyType.Alias) && compositionPropertyType.VariesByCulture() == (culture != null) && !(segment == "*") && compositionPropertyType.VariesBySegment() == (segment != null))
					{
						elementTypeValidationModel.AddPropertyTypeValidation(new PropertyTypeValidationModel(compositionPropertyType, null, $"{group.Path}[{i}].{valuesJsonPathPart}[{JsonPathExpression.MissingPropertyValue(compositionPropertyType.Alias, culture, segment)}].value"));
					}
				}
				yield return elementTypeValidationModel;
			}
		}
	}
}

