/* Site-wide styles below. Vue custom elements have their own shadow-DOM styles,
   but content passed into their slots renders in the light DOM and is styled here. */

/* Umbraco's block-grid renderer ships markup + inline CSS variables but no
   stylesheet, so the grid chrome is laid out here (the local partials in
   Views/Partials/blockgrid/ stay untouched). */
.umb-block-grid {
  display: grid;
  grid-template-columns: repeat(var(--umb-block-grid--grid-columns, 12), minmax(0, 1fr));
  column-gap: 2rem;
  row-gap: 2rem;
}
.umb-block-grid__layout-container {
  display: contents;
}
.umb-block-grid__layout-item {
  grid-column: span var(--umb-block-grid--item-column-span, 12);
  grid-row: span var(--umb-block-grid--item-row-span, 1);
  min-width: 0;
}
.umb-block-grid__area-container {
  display: grid;
  grid-template-columns: repeat(var(--umb-block-grid--area-grid-columns, 12), minmax(0, 1fr));
  column-gap: 2rem;
  row-gap: 2rem;
}
.umb-block-grid__area {
  display: grid;
  grid-column: span var(--umb-block-grid--area-column-span, 12);
  grid-row: span var(--umb-block-grid--area-row-span, 1);
  min-width: 0;
}

/* Tiptap rich text output inside the RichText block component. */
.richtext h2 {
  margin-top: 2rem;
  font-size: 1.5rem;
  line-height: 1.25;
  font-weight: 700;
}
.richtext p {
  margin: 1rem 0;
  line-height: 1.75;
}
.richtext ol,
.richtext ul {
  margin: 1rem 0;
  padding-left: 1.5rem;
}
.richtext ol {
  list-style: decimal;
}
.richtext ul {
  list-style: disc;
}
.richtext li {
  margin: 0.35rem 0;
}
